'use client'

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from 'react'
import { OrbitTilesEngine, orbitLayout } from './orbit-tiles.engine'

export interface OrbitTilesItem {
  image: string
  alt?: string
}

export interface OrbitTilesOptions {
  radiusX: number
  radiusY: number
  tileWidth: number
  tileHeight: number
  speed: number
  tilt: number
  roll: number
  perspective: number
  blur: number
  dimming: number
  pauseOnHover: boolean
  drag: boolean
}

export interface OrbitTilesProps extends Partial<OrbitTilesOptions> {
  items: OrbitTilesItem[]
  className?: string
  style?: CSSProperties
}

export const orbitTilesDefaults: OrbitTilesOptions = {
  radiusX: 520,
  radiusY: 260,
  tileWidth: 200,
  tileHeight: 250,
  speed: 10,
  tilt: 22,
  roll: -12,
  perspective: 1500,
  blur: 8,
  dimming: 0.6,
  pauseOnHover: true,
  drag: true,
}

const MAX_DT = 1 / 30
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

interface DragState {
  active: boolean
  x: number
}

function subscribeMotion(onChange: () => void) {
  const query = window.matchMedia(MOTION_QUERY)
  query.addEventListener('change', onChange)
  return () => query.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

export function OrbitTiles({
  items,
  radiusX = orbitTilesDefaults.radiusX,
  radiusY = orbitTilesDefaults.radiusY,
  tileWidth = orbitTilesDefaults.tileWidth,
  tileHeight = orbitTilesDefaults.tileHeight,
  speed = orbitTilesDefaults.speed,
  tilt = orbitTilesDefaults.tilt,
  roll = orbitTilesDefaults.roll,
  perspective = orbitTilesDefaults.perspective,
  blur = orbitTilesDefaults.blur,
  dimming = orbitTilesDefaults.dimming,
  pauseOnHover = orbitTilesDefaults.pauseOnHover,
  drag = orbitTilesDefaults.drag,
  className,
  style,
}: OrbitTilesProps) {
  const count = items.length
  const reduced = useReducedMotion()
  const engineRef = useRef<OrbitTilesEngine | null>(null)
  if (!engineRef.current) engineRef.current = new OrbitTilesEngine({ count, speed, instant: false })
  const engine = engineRef.current
  const [angle, setAngle] = useState(() => engine.angle)
  const rootRef = useRef<HTMLDivElement>(null)
  const wakeRef = useRef<() => void>(() => {})
  const dragRef = useRef<DragState>({ active: false, x: 0 })

  const wake = useCallback(() => wakeRef.current(), [])

  const publish = useCallback(() => {
    const next = engine.angle
    setAngle((current) => (current === next ? current : next))
  }, [engine])

  useEffect(() => {
    engine.setOptions({ count, speed, instant: reduced })
    wake()
  }, [engine, wake, count, speed, reduced])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    let visible = true
    let frame = 0
    let last = 0

    const loop = (now: number) => {
      frame = 0
      if (!visible) return
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 1 / 60
      last = now
      engine.tick(dt)
      publish()
      if (!engine.idle) frame = requestAnimationFrame(loop)
      else last = 0
    }

    const start = () => {
      if (frame || !visible) return
      last = 0
      frame = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      last = 0
    }

    wakeRef.current = start
    start()

    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      if (visible) start()
      else stop()
    })
    intersection.observe(root)

    const onVisibility = () => {
      if (document.hidden) stop()
      else start()
    }
    document.addEventListener('visibilitychange', onVisibility)

    return () => {
      stop()
      intersection.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
      wakeRef.current = () => {}
    }
  }, [engine, publish])

  const onPointerEnter = () => {
    if (!pauseOnHover) return
    engine.setHover(true)
    wake()
  }

  const onPointerLeave = () => {
    engine.setHover(false)
    wake()
  }

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (!drag || (e.pointerType === 'mouse' && e.button !== 0)) return
    e.currentTarget.setPointerCapture(e.pointerId)
    dragRef.current = { active: true, x: e.clientX }
    engine.dragStart()
    wake()
  }

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const state = dragRef.current
    if (!state.active) return
    const dx = e.clientX - state.x
    state.x = e.clientX
    engine.dragMove(dx, radiusX)
    wake()
  }

  const finishDrag = () => {
    if (!dragRef.current.active) return
    dragRef.current.active = false
    engine.dragEnd()
    wake()
  }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowLeft') engine.nudge(-1)
    else if (e.key === 'ArrowRight') engine.nudge(1)
    else return
    e.preventDefault()
    wake()
  }

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label="Orbiting tiles"
      tabIndex={0}
      className={[
        'uig-orbit-tiles',
        'overflow-hidden select-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      style={{ cursor: drag ? 'grab' : undefined, touchAction: 'pan-y', ...style }}
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={finishDrag}
      onPointerCancel={finishDrag}
      onLostPointerCapture={finishDrag}
      onKeyDown={onKeyDown}
    >
      <div className="uig-orbit-tiles__stage relative h-full w-full">
        {items.map((item, index) => {
          const tile = orbitLayout(angle, index, count, radiusX, radiusY, tilt, roll, perspective)
          const back = 1 - tile.depth
          const softness = blur * back * back
          return (
            <figure
              key={`${item.image}-${index}`}
              className="uig-orbit-tiles__tile absolute top-1/2 left-1/2 m-0 overflow-hidden rounded-lg"
              style={{
                width: tileWidth,
                height: tileHeight,
                zIndex: 1000 + Math.round(tile.z),
                opacity: 1 - dimming * back,
                filter: softness > 0.2 ? `blur(${softness.toFixed(1)}px)` : undefined,
                transform: `translate(-50%, -50%) translate3d(${tile.x.toFixed(1)}px, ${tile.y.toFixed(1)}px, 0) scale(${tile.scale.toFixed(3)})`,
                willChange: 'transform',
              }}
            >
              <img
                src={item.image}
                alt={item.alt ?? ''}
                draggable={false}
                className="uig-orbit-tiles__image block h-full w-full object-cover"
              />
            </figure>
          )
        })}
      </div>
    </div>
  )
}

export interface OrbitTilesEngineOptions {
  count: number
  speed: number
  instant: boolean
}

export interface OrbitTileLayout {
  x: number
  y: number
  scale: number
  depth: number
  z: number
}

type Mode = 'auto' | 'drag' | 'coast' | 'settle'

const TAU = Math.PI * 2
const DEG = Math.PI / 180
const FRICTION = 2.6
const BLEND = 5
const SPRING = 90
const DAMPING = 2 * Math.sqrt(SPRING)
const REST = 0.0005
const LIFT = 0.55

// Places one tile on a tilted, rolled ring seen with perspective
export function orbitLayout(
  angle: number,
  index: number,
  count: number,
  radiusX: number,
  radiusY: number,
  tilt: number,
  roll: number,
  perspective: number,
): OrbitTileLayout {
  const a = angle + (index * TAU) / Math.max(1, count)
  const px = radiusX * Math.sin(a)
  const forward = radiusY * Math.cos(a)
  const tiltRad = tilt * DEG
  const rollRad = roll * DEG
  // Lift the ring so the front tile sits near the middle
  const py = forward * Math.sin(tiltRad) - radiusY * Math.sin(tiltRad) * LIFT
  const z = forward * Math.cos(tiltRad)
  const x = px * Math.cos(rollRad) - py * Math.sin(rollRad)
  const y = px * Math.sin(rollRad) + py * Math.cos(rollRad)
  const scale = perspective / Math.max(1, perspective - z)
  return { x: x * scale, y: y * scale, scale, depth: (Math.cos(a) + 1) / 2, z }
}

export class OrbitTilesEngine {
  angle = 0
  velocity = 0
  idle = false
  count: number
  speed: number
  instant: boolean
  hovered = false
  private mode: Mode = 'auto'
  private target = 0
  private dragDelta = 0

  constructor(options: OrbitTilesEngineOptions) {
    this.count = options.count
    this.speed = options.speed
    this.instant = options.instant
    this.velocity = this.autoVelocity
  }

  get step() {
    return TAU / Math.max(1, this.count)
  }

  private get autoVelocity() {
    return this.instant || this.hovered ? 0 : -this.speed * DEG
  }

  setOptions(next: Partial<OrbitTilesEngineOptions>) {
    if (next.count !== undefined) this.count = next.count
    if (next.speed !== undefined) this.speed = next.speed
    if (next.instant !== undefined) this.instant = next.instant
    if (this.instant && this.mode !== 'drag') {
      this.velocity = 0
      this.mode = 'auto'
    }
    this.idle = false
  }

  setHover(hovered: boolean) {
    this.hovered = hovered
    this.idle = false
  }

  dragStart() {
    this.mode = 'drag'
    this.velocity = 0
    this.dragDelta = 0
    this.idle = false
  }

  dragMove(dx: number, radiusX: number) {
    if (this.mode !== 'drag') return
    const delta = dx / Math.max(40, radiusX)
    this.angle += delta
    this.dragDelta += delta
  }

  dragEnd() {
    if (this.mode !== 'drag') return
    this.mode = this.instant ? 'auto' : 'coast'
    if (this.instant) this.velocity = this.autoVelocity
    this.idle = false
  }

  nudge(steps: number) {
    if (this.mode === 'drag') return
    const base = this.mode === 'settle' ? this.target : this.angle
    this.target = Math.round(base / this.step) * this.step - steps * this.step
    if (this.instant) {
      this.angle = this.target
      this.velocity = 0
      this.mode = 'auto'
    } else {
      this.mode = 'settle'
    }
    this.idle = false
  }

  tick(dt: number) {
    switch (this.mode) {
      case 'drag': {
        const sampled = this.dragDelta / Math.max(dt, 0.001)
        this.velocity += (sampled - this.velocity) * 0.5
        this.dragDelta = 0
        break
      }
      case 'coast': {
        this.angle += this.velocity * dt
        this.velocity *= Math.exp(-FRICTION * dt)
        if (Math.abs(this.velocity) < Math.abs(this.autoVelocity) + 0.05) this.mode = 'auto'
        break
      }
      case 'settle': {
        const diff = this.target - this.angle
        this.velocity += (SPRING * diff - DAMPING * this.velocity) * dt
        this.angle += this.velocity * dt
        if (Math.abs(diff) < 0.002 && Math.abs(this.velocity) < 0.01) {
          this.angle = this.target
          this.mode = 'auto'
        }
        break
      }
      case 'auto': {
        const goal = this.autoVelocity
        this.velocity += (goal - this.velocity) * (1 - Math.exp(-BLEND * dt))
        this.angle += this.velocity * dt
        break
      }
    }
    if (this.angle > TAU || this.angle < -TAU) this.angle %= TAU
    this.idle = this.mode === 'auto' && this.autoVelocity === 0 && Math.abs(this.velocity) < REST
  }
}
